'use strict';
// Standalone server transport. Sites keeps its existing HTTP client.
const OnlineUI=(()=>{
 let ticket=null,matchId=null,gate=0,predicted=null,pending=[],seq=0,searching=false,live=false,ended=false,generation=0,socket=null,reconnectTimer=null,heartbeat=null,queueInfo=null,localCount=1,offset=0,ping=0,lastReply=0,lastClock=-Infinity,requestSeq=0;
 const sessionKey='speedway-online-ticket-ws-v1',requests=new Map(),corrections=new Map(),frames=[];
 function persist(){try{if(ticket)sessionStorage.setItem(sessionKey,JSON.stringify({ticket,matchId}));else sessionStorage.removeItem(sessionKey)}catch{}}
 function notice(text,error=false){$('online-status').textContent=text;$('online-status').classList.toggle('error',error)}
 function connectionLabel(){return !socket||socket.readyState!==WebSocket.OPEN||Date.now()-lastReply>1500?'ŁĄCZENIE…':`ONLINE · ${Math.round(ping)} ms`}
 function render(){if(live&&state!=='menu')return;const active=raceMode==='online';$('online-panel').classList.toggle('hidden',!active);if(!active)return;$('online-cancel').classList.toggle('hidden',!searching);$('start').disabled=searching;$('start').textContent=searching?'SZUKAMY RYWALI':matchId?'WRÓĆ DO BIEGU':'SZUKAJ BIEGU ONLINE';document.querySelectorAll('#name-fields input').forEach(input=>input.disabled=searching||live);if(queueInfo){$('online-wait').textContent=`${queueInfo.players.length}/4 graczy · do ${Math.max(0,Math.ceil((queueInfo.deadline-(Date.now()+offset))/1000))} s`;$('online-players').replaceChildren(...Array.from({length:4},(_,i)=>{const row=document.createElement('li');row.textContent=queueInfo.players[i]?.name||'Czekamy na zawodnika…';return row}))}else{$('online-wait').textContent='Jedna kolejka. Cztery motocykle.';$('online-players').replaceChildren()}}
 function send(value){if(socket?.readyState!==WebSocket.OPEN)throw Error('Połączenie przerwane. Wracamy na tor…');socket.send(JSON.stringify(value))}
 function request(route,body){const id=++requestSeq;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{requests.delete(id);reject(Error('Serwer jeszcze nie odpowiedział. Ponawiamy…'))},5000);requests.set(id,{resolve,reject,timer});try{send({type:'request',id,route,body})}catch(e){clearTimeout(timer);requests.delete(id);reject(e)}})}
 function process(data){if(data.state==='waiting'){queueInfo=data;searching=true;notice('Szukamy ludzi. Po 20 sekundach wolne miejsca zajmą boty.');render()}else if(data.world)accept(data)}
 function connect(run){return new Promise((resolve,reject)=>{const start=Date.now(),ws=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/ws`);socket=ws;let welcomed=false;const timeout=setTimeout(()=>{ws.close();reject(Error('Nie udało się połączyć. Ponawiamy…'))},6000);
 ws.onopen=()=>ws.send(JSON.stringify({type:'hello',ticket}));ws.onmessage=event=>{if(run!==generation||socket!==ws)return;let msg;try{msg=JSON.parse(event.data)}catch{return}lastReply=Date.now();
 if(msg.type==='welcome'){welcomed=true;clearTimeout(timeout);ping=Date.now()-start;offset=msg.serverNow-(start+Date.now())/2;resolve();return}
 if(msg.type==='pong'){const end=Date.now();ping=end-msg.clientAt;const sample=msg.serverNow-(msg.clientAt+end)/2;offset+=Math.max(-3,Math.min(3,(sample-offset)*.2));return}
 if(msg.type==='reply'||msg.type==='error'){const pendingRequest=requests.get(msg.id);if(pendingRequest){clearTimeout(pendingRequest.timer);requests.delete(msg.id);msg.type==='error'?pendingRequest.reject(Object.assign(Error(msg.error),{status:msg.status})):pendingRequest.resolve(msg.data)}else if(msg.type==='error'){notice(msg.error,true);if(!welcomed){clearTimeout(timeout);ws.close();reject(Error(msg.error))}}return}
 if(msg.type==='waiting')process(msg.data);if(msg.type==='matched'){matchId=msg.matchId;searching=false;queueInfo=null;persist();render()}if(msg.type==='state')process(msg.data);
 };ws.onerror=()=>{};ws.onclose=()=>{clearTimeout(timeout);if(!welcomed)reject(Error('Połączenie przerwane.'));if(socket!==ws)return;for(const r of requests.values()){clearTimeout(r.timer);r.reject(Error('Połączenie przerwane.'))}requests.clear();if(run===generation&&!ended&&(searching||live)){notice('Połączenie się urwało. Wracamy na tor…',true);clearTimeout(reconnectTimer);reconnectTimer=setTimeout(()=>resumeConnection(run),500)}};
 })}
 async function resumeConnection(run){try{await connect(run);if(run!==generation)return;if(matchId)process(await request('match',{matchId,commands:pending.slice(0,16)}));else process(await request('queue',{action:'join',name:playerNames[0]}));clearInterval(heartbeat);heartbeat=setInterval(()=>{if(run!==generation)return;try{send({type:'ping',clientAt:Date.now()});if(matchId&&pending.length)request('match',{matchId,commands:pending.slice(0,16)}).then(process).catch(()=>{})}catch{}},1000)}catch(e){if(run!==generation)return;if(e.status===404){matchId=null;pending=[];seq=0;live=false;menu();persist()}notice(e.message,true);if(searching||live)reconnectTimer=setTimeout(()=>resumeConnection(run),700)}}
 function replay(world,now){for(const command of pending){const at=Math.max(world.clock,Math.min(now,command.at));OnlineRace.advance(world,at,.3);OnlineRace.input(world,gate,command.action,at)}OnlineRace.advance(world,now,.3)}
 function accept(data){if(ended||!data.world||data.world.version!==1||data.world.racers?.length!==4||!Number.isInteger(data.gate)||!Number.isInteger(data.ack))return;if(data.world.clock<lastClock)return;lastClock=data.world.clock;matchId=data.matchId;gate=data.gate;pending=pending.filter(c=>c.seq>data.ack);seq=Math.max(seq,data.ack);const fresh=!live,old=racers[0],world=data.world;
 predicted={...world,racers:world.racers.map(r=>({...r}))};replay(predicted,Date.now()+offset);frames.push({clock:world.clock,racers:world.racers.map(r=>({...r}))});while(frames.length>16)frames.shift();corrections.clear();if(!fresh&&old?.gate===gate&&world.phase!=='result'){const target=predicted.racers[gate],distance=Math.hypot(old.x-target.x,old.y-target.y);if(distance<80)corrections.set(gate,{x:old.x-target.x,y:old.y-target.y})}
 if(fresh){live=true;searching=false;queueInfo=null;raceMode='online';humanCount=1;level='normal';trackChoice=world.track;setTrack(world.track);particles=[];showOnlineRace();persist()}present();
 if(world.phase==='result'){predicted={...world,racers:world.racers.map(r=>({...r}))};corrections.clear();frames.length=0;present();ended=true;live=false;searching=false;ticket=null;matchId=null;persist();clearInterval(heartbeat);socket?.close(1000,'Finished');finishRace()}else notice('Bieg online trwa. Każdy jedzie na swoim ekranie.');
 }
 function remotePose(g,now){if(!frames.length)return predicted.racers[g];const time=now-100;let a=frames[0],b=frames.at(-1);for(let i=1;i<frames.length;i++)if(frames[i].clock>=time){a=frames[i-1];b=frames[i];break}else a=frames[i];const left=a.racers[g],right=b.racers[g],t=b.clock>a.clock?Math.max(0,Math.min(1,(time-a.clock)/(b.clock-a.clock))):1;return {...right,x:left.x+(right.x-left.x)*t,y:left.y+(right.y-left.y)*t,angle:left.angle+norm(right.angle-left.angle)*t,poseLeg:left.poseLeg+(right.poseLeg-left.poseLeg)*t,poseDrift:left.poseDrift+(right.poseDrift-left.poseDrift)*t}}
 function present(){if(!predicted)return;const order=[gate,...[0,1,2,3].filter(g=>g!==gate)],prior=new Map(racers.map(r=>[r.gate,r]));racers=order.map((g,i)=>{const source=g===gate?predicted.racers[g]:remotePose(g,Date.now()+offset),shift=corrections.get(g);return {...source,x:source.x+(shift?.x||0),y:source.y+(shift?.y||0),i,human:i===0,name:source.auto?'BOT · '+source.name:source.name,inputs:prior.get(g)?.inputs||new Set()}});elapsed=predicted.elapsed;state=predicted.phase==='result'?'finishing':predicted.phase;updateControls();updateHud();updateCenterEvent();$('red-lamp').classList.toggle('on',state==='red');$('signal').classList.toggle('hidden',state!=='red'&&elapsed>1.3);$('signal-text').textContent=state==='red'?'CZEKAJ':'START!'}
 function tick(dt){if(!live||!predicted)return;if(Date.now()-lastReply<500)OnlineRace.advance(predicted,Date.now()+offset,.08);const decay=Math.exp(-dt*12);for(const shift of corrections.values()){shift.x*=decay;shift.y*=decay}present();racers.forEach(r=>emitGravel(r,dt));particles=particles.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;return p.life>0})}
 function input(action){if(!live||!predicted||pending.length>=64)return;const command={seq:++seq,action,at:Date.now()+offset};pending.push(command);OnlineRace.advance(predicted,command.at,.08);OnlineRace.input(predicted,gate,action,command.at);present();if(socket?.readyState===WebSocket.OPEN){const run=generation;request('match',{matchId,commands:pending.slice(0,16)}).then(data=>{if(run===generation&&!ended)process(data)}).catch(e=>{if(run===generation&&!ended)notice(e.message,true)})}}
 function releaseAll(){if(live&&predicted?.racers[gate]?.held)input('release');inputMap.clear()}
 function stop(){generation++;clearTimeout(reconnectTimer);clearInterval(heartbeat);searching=false;live=false;socket?.close(1000,'Leaving');socket=null;for(const r of requests.values()){clearTimeout(r.timer);r.reject(Error('Bieg zakończony.'))}requests.clear()}
 function leave(){if(socket?.readyState===WebSocket.OPEN)try{send({type:'request',id:++requestSeq,route:matchId?'match':'queue',body:matchId?{matchId,leave:true}:{action:'cancel'}})}catch{}stop();ticket=null;matchId=null;predicted=null;pending=[];seq=0;ended=false;frames.length=0;lastClock=-Infinity;queueInfo=null;persist();render()}
 function launch(){if(searching||live)return;generation++;ended=false;lastClock=-Infinity;if(!ticket){ticket=crypto.randomUUID()+'-'+crypto.randomUUID();pending=[];seq=0}searching=!matchId;persist();render();notice('Łączymy Cię ze stawką…');resumeConnection(generation)}
 function setMode(mode){if(['red','racing','finishing'].includes(state))return;if(mode==='online'){if(raceMode!=='online'){if(raceMode==='gp')GPUI.setMode('quick');localCount=humanCount;humanCount=1;raceMode='online';gpHeat=null;document.body.classList.remove('gp-mode','mystery-track');document.body.classList.add('online-mode');renderNames();updateMystery();GPUI.render()}render();return}leave();document.body.classList.remove('online-mode');raceMode='quick';humanCount=localCount;renderNames();updateMystery();GPUI.setMode(mode);render()}
 function newRace(){leave();menu();launch()}
 function back(){leave();menu()}
 function init(){try{const saved=JSON.parse(sessionStorage.getItem(sessionKey)||'null');if(saved&&/^[a-zA-Z0-9-]{64,100}$/.test(saved.ticket)){ticket=saved.ticket;matchId=saved.matchId||null}}catch{}$('online-cancel').onclick=()=>{leave();notice('Wyszukiwanie przerwane. Stawka poczeka.')};document.addEventListener('visibilitychange',()=>{if(document.hidden)releaseAll()});window.addEventListener('pagehide',releaseAll);render()}
 return {init,setMode,render,launch,tick,input,releaseAll,newRace,back,connectionLabel};
})();
